from __future__ import annotations

import base64
import zlib
from pathlib import Path

ROOT = Path.cwd()

PAYLOADS = {
    "schema": "",
    "valid": "",
    "invalid": "",
    "test": "",
    "evidence": "",
}


def decode(name: str) -> str:
    return zlib.decompress(base64.b64decode(PAYLOADS[name])).decode("utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


schema = decode("schema")
write("schemas/mstr-self-alignment-generation-v0.schema.json", schema)
write(
    "specs/002-code-model-supremacy-foundation/contracts/"
    "mstr-self-alignment-generation-v0.schema.json",
    schema,
)
write(
    "tests/fixtures/schemas/valid/mstr-self-alignment-generation-v0.json",
    decode("valid"),
)
write(
    "tests/fixtures/schemas/invalid/mstr-self-alignment-generation-v0.json",
    decode("invalid"),
)
write("tests/contract/test_self_alignment_contract.py", decode("test"))
write("evidence/mstr-000b/B018-self-alignment-contract.md", decode("evidence"))

schemas_path = ROOT / "src/mstr_qualify/schemas.py"
schemas_text = schemas_path.read_text(encoding="utf-8")
schemas_anchor = (
    '    "mstr-software-evolution-record-v0": '
    '"mstr-software-evolution-record-v0.schema.json",\n'
)
if schemas_text.count(schemas_anchor) != 1:
    raise SystemExit("schemas.py registration anchor mismatch")
schemas_replacement = schemas_anchor + (
    "    # MSTR-000B B018: execution-filtered student self-alignment contract.\n"
    '    "mstr-self-alignment-generation-v0": '
    '"mstr-self-alignment-generation-v0.schema.json",\n'
)
schemas_path.write_text(
    schemas_text.replace(schemas_anchor, schemas_replacement),
    encoding="utf-8",
)

cli_path = ROOT / "src/mstr_qualify/cli.py"
cli_text = cli_path.read_text(encoding="utf-8")
cli_anchor = (
    '    "mstr.software-evolution-record.v0": '
    '"mstr-software-evolution-record-v0",\n'
)
if cli_text.count(cli_anchor) != 1:
    raise SystemExit("cli.py schema-version anchor mismatch")
cli_replacement = cli_anchor + (
    "    # MSTR-000B B018 execution-filtered student self-alignment contract.\n"
    '    "mstr.self-alignment-generation.v0": '
    '"mstr-self-alignment-generation-v0",\n'
)
cli_path.write_text(cli_text.replace(cli_anchor, cli_replacement), encoding="utf-8")
